import torch
import torch.nn as nn
from torch.autograd import Function
from torch.utils.cpp_extension import load_inline

fused_op_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_op_kernel(const float* input, const float* scaling_factor, const float* bias, float* output, 
                                int num_elements, int channels, int channel_stride) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        int channel = (idx / channel_stride) % channels;
        float x = input[idx];
        float scale = scaling_factor[channel];
        float b = bias[channel];
        x *= scale;
        x = tanhf(x);
        x *= b;
        x = 1.0f / (1.0f + expf(-x));
        output[idx] = x;
    }
}

torch::Tensor fused_op_cuda(torch::Tensor input, torch::Tensor scaling_factor, torch::Tensor bias) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    int channels = input.size(1);
    int channel_stride = input.size(2) * input.size(3) * input.size(4);

    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    fused_op_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        scaling_factor.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        channels,
        channel_stride
    );

    return output;
}
"""

fused_op_cpp_source = "torch::Tensor fused_op_cuda(torch::Tensor input, torch::Tensor scaling_factor, torch::Tensor bias);"

fused_op = load_inline(
    name='fused_op',
    cpp_sources=fused_op_cpp_source,
    cuda_sources=fused_op_source,
    functions=['fused_op_cuda'],
    verbose=True
)

class FusedOp(Function):
    @staticmethod
    def forward(ctx, input, scaling_factor, bias):
        ctx.save_for_backward(input, scaling_factor, bias)
        return fused_op.fused_op_cuda(input, scaling_factor, bias)

    @staticmethod
    def backward(ctx, grad_output):
        input, scaling_factor, bias = ctx.saved_tensors
        with torch.enable_grad():
            scaled = input * scaling_factor
            tanh_val = torch.tanh(scaled)
            z = tanh_val * bias
            sigmoid_val = torch.sigmoid(z)
            grad_input, grad_scaling, grad_bias = torch.autograd.grad(
                sigmoid_val,
                (input, scaling_factor, bias),
                grad_output,
                retain_graph=True
            )
        return grad_input, grad_scaling, grad_bias

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor, bias_shape):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.scaling_factor = nn.Parameter(torch.randn(bias_shape))
        self.bias = nn.Parameter(torch.randn(bias_shape))

    def forward(self, x):
        x = self.conv(x)
        x = FusedOp.apply(x, self.scaling_factor, self.bias)
        return x
